import { useEffect, useRef, useState } from 'react';

export default function DirtyModalGuard() {
  const [saved, setSaved] = useState({"name":"NH-WS-014","branch":"North Hub"});
  const [original, setOriginal] = useState(saved);
  const [draft, setDraft] = useState(saved);
  const [confirm, setConfirm] = useState(false);
  const [message, setMessage] = useState('');
  const modal = useRef<HTMLDialogElement>(null);
  const name = useRef<HTMLInputElement>(null);
  const keep = useRef<HTMLButtonElement>(null);
  const opener = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (modal.current?.open) (confirm ? keep.current : name.current)?.focus();
  }, [confirm]);
  function close() {
    modal.current?.close();
    setConfirm(false);
    opener.current?.focus();
  }
  function requestClose() {
    if (confirm) { setConfirm(false); return; }
    if (draft.name !== original.name || draft.branch !== original.branch) setConfirm(true);
    else close();
  }
  return <section className="grid min-w-0 gap-3 p-3 text-start text-sm">
    <p><strong>{saved.name}</strong> · {saved.branch}</p>
    <button type="button" className="w-fit rounded-sm border px-3 py-2 font-semibold" ref={opener} onClick={() => {
      setOriginal({...saved}); setDraft({...saved}); setConfirm(false);
      modal.current?.showModal(); name.current?.focus();
    }}>Edit record</button>
    <p role="status">{message}</p>
    <dialog className="m-auto max-h-[90dvh] w-[min(22rem,90vw)] overflow-auto rounded border bg-[var(--bg-surface,#fff)] p-0 text-[var(--ink-primary,#101412)] backdrop:bg-black/40" ref={modal} aria-label={confirm ? 'Discard unsaved changes?' : 'Edit record'}
      onCancel={e => { e.preventDefault(); requestClose(); }} onClick={e => { if (e.target === e.currentTarget) requestClose(); }}>
      {confirm ? <div className="grid gap-3 p-4">
        <h3 className="font-bold">Discard unsaved changes?</h3><p>Your saved record will stay as it was when you opened it.</p>
        <div className="flex flex-wrap gap-2"><button type="button" ref={keep} className="w-fit rounded-sm border px-3 py-2 font-semibold" onClick={() => setConfirm(false)}>Keep editing</button>
          <button type="button" className="w-fit rounded-sm border px-3 py-2 font-semibold bg-emerald-800 text-white" onClick={close}>Discard changes</button></div>
      </div> : <form className="grid gap-3 p-4" onSubmit={e => {
        e.preventDefault(); if (!draft.name.trim()) return;
        setSaved({ ...draft, name: draft.name.trim() }); setMessage('Changes saved.'); close();
      }}>
        <h3 className="font-bold">Edit record</h3>
        <label className="grid gap-1">Asset name<input ref={name} className="w-full rounded-sm border bg-transparent p-2" required maxLength={80} value={draft.name}
          onChange={e => setDraft({...draft, name:e.target.value})} /></label>
        <label className="grid gap-1">Branch<select className="w-full rounded-sm border bg-transparent p-2" value={draft.branch} onChange={e => setDraft({...draft, branch:e.target.value})}><option>North Hub</option><option>Harbor Office</option><option>Central Campus</option></select></label>
        <div className="flex flex-wrap gap-2"><button type="submit" className="w-fit rounded-sm border px-3 py-2 font-semibold bg-emerald-800 text-white" disabled={!draft.name.trim()}>Save changes</button>
          <button type="button" className="w-fit rounded-sm border px-3 py-2 font-semibold" onClick={requestClose}>Close</button></div>
      </form>}
    </dialog>
  </section>;
}
